-- ===== accounts-002-recovery.sql =====
-- Authenticator recovery (Report B preview authorisation, item 4).
--
-- ADDITIVE ONLY (CREATE ... IF NOT EXISTS). Applied only by scripts/db/migrate.cjs.
--
-- Single-use recovery codes. Only an HMAC of each code (keyed by
-- ACCOUNTS_SECRET_KEY) is stored, so a copy of the database alone cannot be
-- used to guess them. A used code keeps its row (used_at) for the audit trail.
CREATE TABLE IF NOT EXISTS acct_recovery_codes (
  user_id     UUID NOT NULL REFERENCES acct_users(id) ON DELETE CASCADE,
  code_hmac   TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL,
  used_at     TIMESTAMPTZ,
  PRIMARY KEY (user_id, code_hmac)
);
CREATE INDEX IF NOT EXISTS acct_recovery_codes_unused ON acct_recovery_codes (user_id) WHERE used_at IS NULL;

INSERT INTO acct_schema_migrations (name, sha256) VALUES ('accounts-002-recovery.sql', 'c9e03c39dcf2f615c2b52f49bc3f20d074b77b591343301182904a946551562a') ON CONFLICT (name) DO NOTHING;

-- ===== accounts-003-test-outbox.sql =====
-- Preview test-email outbox (Report B preview authorisation, item 5).
--
-- ADDITIVE ONLY (CREATE ... IF NOT EXISTS). Applied only by scripts/db/migrate.cjs.
--
-- Used only when ACCOUNTS_MAIL_MODE is exactly "outbox" on the protected
-- preview: account emails (verification, reset, invitation) to allow-listed
-- TEST addresses are stored here instead of being sent, so testers can open
-- the real links without any message leaving the system. Messages to any
-- other address are refused and never stored.
CREATE TABLE IF NOT EXISTS acct_test_outbox (
  id          UUID PRIMARY KEY,
  to_addr     TEXT NOT NULL,
  kind        TEXT NOT NULL CHECK (kind IN ('verify_email', 'reset_password', 'invite')),
  subject     TEXT NOT NULL,
  body        TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS acct_test_outbox_to ON acct_test_outbox (to_addr, created_at DESC);

INSERT INTO acct_schema_migrations (name, sha256) VALUES ('accounts-003-test-outbox.sql', 'ca93d9e46215d74b23a71abb2279887539b9f072fb135a7c0e46a77cac166836') ON CONFLICT (name) DO NOTHING;

-- ===== accounts-004-review-decisions.sql =====
-- Review decisions other than approval: REJECTION of an exact revision
-- (Report B live-database authorisation, item 7: approval, rejection,
-- revocation and re-approval).
--
-- ADDITIVE ONLY (CREATE ... IF NOT EXISTS). Applied only by scripts/db/migrate.cjs.
--
-- A rejection is a recorded professional decision by a verified, in-date,
-- in-scope reviewer, with a reason, against ONE revision and its content
-- hash. It never makes a document approved; the document stays DRAFT and
-- shows who rejected it, when and why. A later revision can be approved.
CREATE TABLE IF NOT EXISTS acct_review_decisions (
  id             UUID PRIMARY KEY,
  org_id         UUID NOT NULL,
  project_id     UUID NOT NULL REFERENCES acct_projects(id) ON DELETE CASCADE,
  revision_id    UUID NOT NULL REFERENCES acct_revisions(id) ON DELETE CASCADE,
  revision_hash  TEXT NOT NULL,
  tool           TEXT NOT NULL,
  document_type  TEXT NOT NULL,
  reviewer_id    UUID NOT NULL REFERENCES acct_reviewers(id),
  decision       TEXT NOT NULL CHECK (decision IN ('rejected')),
  reason         TEXT NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS acct_review_decisions_rev ON acct_review_decisions (revision_id, document_type, created_at DESC);

INSERT INTO acct_schema_migrations (name, sha256) VALUES ('accounts-004-review-decisions.sql', '515e136c5fe666304a01322e5d0e794750ced78484ab44bb4036628cec94433c') ON CONFLICT (name) DO NOTHING;

-- ===== accounts-005-database-identity.sql =====
-- Database identity marker (Report B database setup approval, safeguards 2, 4 and 8).
--
-- ADDITIVE ONLY (CREATE ... IF NOT EXISTS). Applied by scripts/db/migrate.cjs or
-- lib/db/migrations/preview-setup.sql.
--
-- One row, set BY THE OWNER, separately in each database:
--   preview database:            INSERT INTO acct_database_identity (role) VALUES ('preview');
--   disaster-recovery test DB:   INSERT INTO acct_database_identity (role) VALUES ('dr-test');
-- The accounts feature refuses to run unless its database says 'preview'; the
-- recovery drill refuses unless the source says 'preview' and the target says
-- 'dr-test'. A production database has no such table, so it can never qualify.
CREATE TABLE IF NOT EXISTS acct_database_identity (
  singleton  BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (singleton),
  role       TEXT NOT NULL CHECK (role IN ('preview', 'dr-test')),
  set_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

